    if(step>32767)step=32767;
}
if(pressed(keys,JOY_RIGHT)) req_turn=(s16)-step;
if(pressed(keys,JOY_LEFT))  req_turn=(s16) step;

if(host_analog_aim && host_aim_turn!=0.0f && !hugkill){
